// Builds the language packs public/data/i18n/<lang>.json from tools/i18n/<lang>/:
//   ui.json        — interface strings
//   content.json   — texts of events, cultures, routes, people, cities, seas, eras (by id)
//   wd.json        — Wikidata event titles (generated by build-wd.js)
//   polities/*.json — translated polity names (English names are the keys; optional)
// Also writes index.json with a version per pack, so browsers that cached a pack know to refresh it.
// Fails if any id in the data has no text in some language.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const ROOT = path.resolve(import.meta.dirname, '..');
const read = p => JSON.parse(fs.readFileSync(path.join(ROOT, p), 'utf8'));
const LANGS = { en: 'English', bg: 'Български' };
const OUT = path.join(ROOT, 'public/data/i18n');
fs.mkdirSync(OUT, { recursive: true });

// Every id the app will look up.
const content = Object.fromEntries(['events', 'cultures', 'routes', 'people', 'cities', 'seas'].map(k => [k, read(`public/data/content/${k}.json`).map(x => x.id)]));
content.eras = read('public/data/content/eras.json').tracks.map(t => t.id);
const wdIds = read('public/data/wd-events.json').map(r => r[5]);

// Every polity name in the borders, including "under the rule of" names.
const polityNames = new Set(Object.keys(read('public/data/entities.json')));
for (const f of fs.readdirSync(path.join(ROOT, 'public/data/borders'))) {
  for (const ft of read(`public/data/borders/${f}`).fc.features) if (ft.properties.s) polityNames.add(ft.properties.s);
}

const nkey = s => s.normalize('NFC').trim();
const index = { default: 'en', langs: {} };
let problems = 0;

for (const [lang, name] of Object.entries(LANGS)) {
  const dir = `tools/i18n/${lang}`;
  const pack = { lang, ui: read(`${dir}/ui.json`), ...read(`${dir}/content.json`), wd: read(`${dir}/wd.json`) };

  for (const [kind, ids] of Object.entries(content)) {
    const miss = ids.filter(id => !pack[kind]?.[id]);
    if (miss.length) { problems++; console.error(`${lang}: ${kind} without text: ${miss.join(', ')}`); }
  }
  const wdMiss = wdIds.filter(id => !pack.wd[id]);
  if (wdMiss.length) { problems++; console.error(`${lang}: ${wdMiss.length} Wikidata events without a title`); }
  const uiMiss = Object.keys(read('tools/i18n/en/ui.json')).filter(k => !(k in pack.ui));
  if (uiMiss.length) { problems++; console.error(`${lang}: ui keys missing: ${uiMiss.join(', ')}`); }

  if (fs.existsSync(path.join(ROOT, dir, 'polities'))) {
    const tr = {};
    for (const f of fs.readdirSync(path.join(ROOT, dir, 'polities')).filter(f => f.endsWith('.json')).sort()) {
      for (const [k, v] of Object.entries(read(`${dir}/polities/${f}`))) tr[nkey(k)] = v;
    }
    pack.polities = {};
    const miss = [];
    for (const n of polityNames) {
      const v = tr[nkey(n)];
      if (v == null) miss.push(n);
      else if (v !== '') pack.polities[n] = v;
    }
    if (miss.length) { problems++; console.error(`${lang}: ${miss.length} polity names without translation, e.g. ${miss.slice(0, 5).join(', ')}`); }
  }

  const body = JSON.stringify(pack);
  fs.writeFileSync(path.join(OUT, `${lang}.json`), body);
  index.langs[lang] = { name, v: crypto.createHash('sha1').update(body).digest('hex').slice(0, 10), kb: Math.round(Buffer.byteLength(body) / 1024) };
  console.log(`${lang}: ${index.langs[lang].kb} KB`);
}
fs.writeFileSync(path.join(OUT, 'index.json'), JSON.stringify(index, null, 2) + '\n');
if (problems) process.exit(1);
